  async function save(){if(readonly()||busy)return false;clearTimeout(saveTimer);if(typeof options.save!=='function')return fail('save','请配置 save 回调');if(!emit(element,'beforechange',{reason:'save',value:getState()})||readonly())return false;const token=++sequence,controller=new win.AbortController();job=controller;busy=true;state.saveStatus='saving';error='';render();try{await service(()=>options.save(state.text,{signal:controller.signal,value:getState()}),controller);if(token!==sequence||disposed)return false;state.saveStatus='saved';emit(element,'action',{reason:'save',value:getState()});}catch(cause){if(token!==sequence||disposed)return false;state.saveStatus='error';error=String(cause.message||cause);emit(element,'error',{reason:'save',message:error});}busy=false;job=null;render();return state.saveStatus==='saved';}
